import sys

def solve():
    a, b, s = map(int, sys.stdin.read().split())
    m = abs(a) + abs(b)
    if s >= m and (s - m) % 2 == 0:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
"}

