def get_parity(permutation):
    """Return the parity of the permutation (even: 0, odd: 1)"""
    parity = 0
    for i in range(len(permutation)):
        for j in range(i + 1, len(permutation)):
            if permutation[i] > permutation[j]:
                parity += 1
    return parity % 2

def solve():
    n = int(input())
    permutation = list(map(int, input().split()))

    # Calculate parity of the permutation
    parity = get_parity(permutation)

    # Calculate expected parity for each method
    petr_swaps = 3 * n
    alex_swaps = 7 * n + 1

    petr_expected_parity = petr_swaps % 2
    alex_expected_parity = alex_swaps % 2

    # Determine which method was used
    if parity == petr_expected_parity:
        print("Petr")
    else:
        print("Um_nik")

solve()
"}

