def solve():
    t = int(input())
    results = []

    for _ in range(t):
        s = input().strip()
        stack = []

        for ch in s:
            stack.append(ch)

            # Check if we can remove a pair
            while len(stack) >= 2:
                a, b = stack[-2], stack[-1]

                # Check if we can remove AB or BB
                if (a == 'A' and b == 'B') or (a == 'B' and b == 'B'):
                    stack.pop()
                    stack.pop()
                else:
                    break

        results.append(len(stack))

    for res in results:
        print(res)

solve()
"}

