def solve():
    n = int(input())

    # Build adjacency list
    from collections import defaultdict
    graph = defaultdict(list)

    for _ in range(2 * n):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    # Try to find a Hamiltonian cycle using backtracking
    visited = [False] * (n + 1)
    path = []

    def dfs(node):
        visited[node] = True
        path.append(node)

        if len(path) == n:
            # Check if last node connects back to first node
            if path[-1] == path[0]:
                return True
            return False

        found = False

        for neighbor in graph[node]:
            if not visited[neighbor] and (len(path) == 1 or neighbor != path[-2]):
                # If path length is 1, we don't have a previous node
                # Otherwise, we need to avoid backtracking
                found = dfs(neighbor)
                if found:
                    break

        if not found:
            visited[node] = False
            path.pop()

        return found

    if not dfs(1):
        print(-1)
    else:
        # We need to check if the path forms a valid cycle
        # Check if last node connects back to first node
        if path[-1] != path[0]:
            print(-1)
        else:
            print(' '.join(map(str, path)))

solve()
