MOD = 1000000007

start = input().strip()
end = input().strip()
k = int(input())
n = len(start)

# Function to split a word at position i (1-indexed)
def split_word(w, pos):
    return w[pos:] + w[:pos]

# BFS to find all reachable states from start
from collections import deque

queue = deque([start])
visited = {start: True}
mapping = {start: 0}

while queue:
    word = queue.popleft()
    for i in range(1, n):
        new_word = split_word(word, i)
        if new_word not in visited:
            visited[new_word] = True
            mapping[new_word] = len(mapping)
            queue.append(new_word)

num_states = len(mapping)

# If end not reachable, answer is 0
if end not in mapping:
    print(0)
    exit()

# DP: dp[t][s] = count of ways to reach state s in t splits
# Use list of arrays for efficiency

dp = [ [0] * num_states for _ in range(k+1) ]
dp[0][mapping[start]] = 1

for t in range(k):
    for s in range(num_states):
        if dp[t][s] == 0:
            continue
        word = None
        for w, idx in mapping.items():
            if idx == s:
                word = w
                break
        for i in range(1, n):
            new_word = split_word(word, i)
            new_idx = mapping[new_word]
            dp[t+1][new_idx] = (dp[t+1][new_idx] + dp[t][s]) % MOD

print(dp[k][mapping[end]])
"}

