from collections import deque, defaultdict

# Find connected components of empty cells
components = []
visited = [[False] * m for _ in range(n)]

for i in range(n):
    for j in range(m):
        if grid[i][j] == '.' and not visited[i][j]:
            # BFS to find component
            queue = deque([(i, j)])
            visited[i][j] = True
            component = [(i, j)]

            while queue:
                x, y = queue.popleft()
                for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if not visited[nx][ny] and grid[nx][ny] == '.':
                            visited[nx][ny] = True
                            component.append((nx, ny))
                            queue.append((nx, ny))
            components.append(component)

# Check if any component is impossible
for comp in components:
    if len(comp) == 1 or len(comp) > 5:
        print(-1)
        exit()

# Color components so adjacent components have different colors
# We'll use a greedy coloring approach

color_index = [0] * len(components)

# Build adjacency list
adj = [[] for _ in range(len(components))]
for i, comp in enumerate(components):
    for (x, y) in comp:
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                # Find which component (nx, ny) belongs to
                for j, comp_j in enumerate(components):
                    if (nx, ny) in comp_j:
                        adj[i].append(j)
                        adj[j].append(i)
                        break

# Greedy coloring
for i in range(len(components)):
    # Try colors in order
    for c in range(1, len(components)+1):
        # Check if this color is used by any adjacent component
        conflict = False
        for j in adj[i]:
            if color_index[j] == c:
                conflict = True
                break
        if not conflict:
            color_index[i] = c
            break

# Output the result
for i in range(n):
    row = []
    for j in range(m):
        if grid[i][j] == '#':
            row.append('#')
        else:
            # Find which component this cell belongs to
            for idx, comp in enumerate(components):
                if (i, j) in comp:
                    row.append(str(color_index[idx]))
                    break
    print(''.join(row))
