import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    l = int(data[1])
    k = int(data[2])

    probabilities = list(map(int, data[3:3+n]))
    capacities = list(map(int, data[3+n:6+n]))

    probs = [p / 100.0 for p in probabilities]

    # DP: dp[tour][huge_prizes][capacity] = probability
    # We start with 0 tours done, 0 huge prizes, k capacity
    dp = {0: {0: {k: 1.0}}}

    for tour in range(n):
        next_dp = {}

        for wins, huge, cap in dp[tour]:
            prob = dp[tour][(wins, huge, cap)]

            # Lose the tour
            new_wins = wins
            new_huge = huge
            new_cap = cap

            if new_wins not in next_dp:
                next_dp[new_wins] = {}
            if new_huge not in next_dp[new_wins]:
                next_dp[new_wins][new_huge] = {}
            next_dp[new_wins][new_huge][new_cap] = prob

            # Win the tour
            new_wins = wins + 1
            new_huge = huge
            new_cap = cap

            win_prob = probs[tour]
            lose_prob = 1.0 - win_prob

            if capacities[tour] == -1:
                # Get a huge prize, need a bag
                new_huge = huge + 1

                if new_huge <= new_cap:
                    # Can carry it, update state
                    if new_wins not in next_dp:
                        next_dp[new_wins] = {}
                    if new_huge not in next_dp[new_wins]:
                        next_dp[new_wins][new_huge] = {}
                    next_dp[new_wins][new_huge][new_cap] = prob * win_prob
            else:
                # Get a bag with capacity ai
