            if new_huge not in next_dp[new_wins]:
                next_dp[new_wins][new_huge] = {}
            next_dp[new_wins][new_huge][new_cap] = prob * lose_prob

        dp[tour + 1] = next_dp

    # Calculate total probability of success
    total = 0.0
    for wins, huge, cap in dp[n]:
