    graph = {i: [] for i in range(1, n + 1)}
    for _ in range(2 * n):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    # Build a degree 2 graph (immediate neighbors)
    degree_2 = {i: [] for i in range(1, n + 1)}
    for i in range(1, n + 1):
        for neighbor in graph[i]:
            # A number has exactly 2 immediate neighbors and 2 separated by one
            # If a node has degree 2, it's an immediate neighbor
            if len(graph[neighbor]) == 2 and neighbor != i:
                degree_2[i].append(neighbor)
                degree_2[neighbor].append(i)

    # Find a starting point (any number with degree 4)
    start = None
    for i in range(1, n + 1):
        if len(graph[i]) == 4:
            start = i
            break

    # Build the circle
    circle = []
    current = start
    prev = None

    for _ in range(n):
        # Find the next number
        next_num = None
        for neighbor in graph[current]:
            if neighbor != prev:
                if len(graph[neighbor]) == 2:
                    # This is an immediate neighbor
                    next_num = neighbor
                    break
                else:
                    # This might be a number separated by one
                    # Check if neighbor is separated by one from both current and next_num
                    if next_num is None:
                        next_num = neighbor
                    else:
                        # Check if neighbor is adjacent to both current and next_num
                        is_adjacent_to_current = current in graph[neighbor]
                        is_adjacent_to_next = next_num in graph[neighbor]

                        if is_adjacent_to_current and is_adjacent_to_next:
                            # neighbor is adjacent to both current and next_num, they are separated by one
                            next_num = neighbor
                            break

        circle.append(current)
        prev = current
        current = next_num

    # Print the result
    print(' '.join(map(str, circle)))

