def parse_artifact_description(desc):
    """Parse a composite artifact description."""
    desc = desc.strip()
    name, rest = desc.split(':', 1)
    name = name.strip()
    rest = rest.strip().split(', ')
    components = {}

    for comp in rest:
        parts = comp.split()
        art_name = parts[0].strip()
        count = int(parts[1])
        components[art_name] = count

    return name, components


