actions = []
n = int(input())
for _ in range(n):
    actions.append(input().split())

possible_letters = set('abcdefghijklmnopqrstuvwxyz')

determined_at = -1
selected_letter = None

# First pass: determine when we know the letter
for i, action in enumerate(actions):
    if action[0] == '!':
        # Shock: selected letter is in word
        word = action[1]
        possible_letters.intersection_update(set(word))
    elif action[0] == '.':
        # No shock: selected letter is not in word
        word = action[1]
        possible_letters.difference_update(set(word))
    elif action[0] == '?':
        # Guess
        # We need to check if we can uniquely determine the letter
        if len(possible_letters) == 1:
            determined_at = i
            selected_letter = possible_letters.pop()
            possible_letters.add(selected_letter)

# Now count excessive shocks from the point we determined it
excessive_shocks = 0
for i, action in enumerate(actions):
    if i >= determined_at and action[0] == '!':
        excessive_shocks += 1
    elif action[0] == '?':
        # This is the last action and it's a correct guess
        if i >= determined_at:
            break

print(excessive_shocks)
"}

