from collections import defaultdict

def solve():
    n = int(input())
    events = []

    for _ in range(n):
        a, t, x = map(int, input().split())
        events.append((t, a, x))

    # Sort by time
    events.sort()

    # Maintain current state
    counts = defaultdict(int)

    # Process events in chronological order
    for t, a, x in events:
        if a == 1:
            counts[x] += 1
        elif a == 2:
            counts[x] -= 1

    # Now answer queries in the order Artem performs them
    # We need to maintain a record of queries and answer them

    # Store original queries with their time
    queries = []

    # Process all events again in original order to find queries
    for t, a, x in events:
        if a == 3:
            queries.append((t, x))

    # Now answer queries in order of increasing time
    queries.sort()

    for t, x in queries:
        # Find all operations with time < t and count net effect
        cnt = 0
        for tt, a, xx in events:
            if tt < t and xx == x:
                if a == 1:
                    cnt += 1
                elif a == 2:
                    cnt -= 1
        print(cnt)

solve()
