import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        line = sys.stdin.readline().strip()
        while line == "":
            line = sys.stdin.readline().strip()
        n, k = map(int, line.split())

        if k >= n:
            # Use type n (since we can use any type from 1 to n and want minimum packages)
            print(n // k)
        else:
            # Find the largest i <= k that divides n
            # We need to buy n/i packages
            # i should be as large as possible
            i = n // k
            while i > k:
                i -= 1
            # Check if i divides n
            while n % i != 0:
                i -= 1
            print(n // i)

if __name__ == "__main__":
    solve()
