    # Check if shape fits at (row, col) without overlap
    # shape is a tuple of cells

    # Check if shape fits in the board
    for (ri, rj) in shape:
        if not is_valid_position(None, row + ri, col + rj, n, m):
            return False

    # Check if shape overlaps with filled cells
    for (ri, rj) in shape:
        if filled_cells.get((row + ri, col + rj), False):
            return False

    # Check if shape overlaps with already placed figures
    for i, j in filled_cells:
        for (ri, rj) in shape:
            if i == row + ri and j == col + rj:
                return False

    return True

def get_adjacent_figures(row, col, grid, filled_cells):
    # Get adjacent cells that are already filled
    adjacent = []
    for (di, dj) in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        ni, nj = row + di, col + dj
        if is_valid_position(None, ni, nj, n, m) and filled_cells.get((ni, nj), False):
            adjacent.append((ni, nj))
    return adjacent

def solve(grid, n, m):
    filled_cells = {}
    used_figures = set()

    def backtrack(empty_cells, used_cells, placed):
        if not empty_cells:
            return True

        # Choose the next cell (simple greedy: first empty cell)
        i, j = empty_cells[0]

        # Try placing each possible figure at (i, j)
        shapes = get_possible_figures(i, j, n, m, filled_cells)

        for shape in shapes:
            if get_fits(grid, i, j, shape, n, m, filled_cells):
                # Check if shape touches any already placed figure
                touches = False
                for (di, dj) in shape:
                    for (pi, pj) in filled_cells:
                        if pi == i + di and pj == j + dj:
                            touches = True
                            break
                    if touches:
                        break

                if not touches:
                    # Place the figure
                    for (di, dj) in shape:
                        filled_cells[(i + di, j + dj)] = True
                        used_cells.append((i + di, j + dj))

                    # Try to place remaining
                    result = backtrack(empty_cells[1:], used_cells, placed + 1)

                    if result:
                        return True

                    # Backtrack
                    for (di, dj) in shape:
                        filled_cells.pop((i + di, j + dj), None)
                    used_cells.pop()

        return False

    empty_cells = get_empty_cells(grid, n, m)
    if not empty_cells:
        return grid

    if backtrack(empty_cells, [], []):
        return grid
    else:
        return None

def main():
    n, m = map(int, sys.stdin.readline().split())
    grid = read_grid(n, m)

    solution = solve(grid, n, m)

    if solution:
        write_grid(solution)
    else:
        print(-1)

if __name__ == '__main__':
    main()

