start = input().strip()
end = input().strip()
k = int(input())

MOD = 10**9 + 7
length = len(start)

# Map each word to an integer index
state_to_index = {}
index_to_state = {}

def hash_word(word):
    if word in state_to_index:
        return state_to_index[word]
    idx = len(state_to_index)
    state_to_index[word] = idx
    index_to_state[idx] = word
    return idx

# dp[step][index] = number of ways to reach that state after step operations
dp = [None for _ in range(k+1)]

dp[0] = [0] * len(state_to_index)
dp[0][hash_word(start)] = 1

# Precompute transitions
transitions = [[] for _ in range(len(state_to_index))]
for idx, word in index_to_state.items():
    for split_pos in range(1, length):
        new_word = word[split_pos:] + word[:split_pos]
        new_idx = hash_word(new_word)
        transitions[idx].append(new_idx)

# Update dp for each step
for step in range(k):
    dp[step+1] = [0] * len(state_to_index)
    for state_idx, ways in enumerate(dp[step]):
        if ways == 0:
            continue
        for next_idx in transitions[state_idx]:
            dp[step+1][next_idx] = (dp[step+1][next_idx] + ways) % MOD

# Convert back to string before output
print(index_to_state[dp[k].index(max(dp[k]))])
"}

