import re

def solve(s):
    # Tokenize the string
    tokens = []
    i = 0
    while i < len(s):
        if i + 2 < len(s) and s[i:i+3] == '...':
            tokens.append(('...', 3))
            i += 3
        elif s[i] == ',':
            tokens.append((',', 1))
            i += 1
        elif s[i] == '':
            # Skip spaces (we'll handle them separately)
            i += 1
        else:
            # Number (digits only)
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(('num', s[i:j]), j - i)
            i = j

    result = []
    last_type = None  # Can be 'num', ',', or '...' (three dots)

    for token, length in tokens:
        if last_type is None:
            # First element
            if token == 'num':
                result.append(token)
            elif token == ',':
                # First element is comma, skip it
                pass
            elif token == '...':
                result.append(token)
        else:
            if token == 'num':
                # If last was a number, we need a space before the new number
                result.append(' ')
                result.append(token)
            elif token == ',':
                # If last was a comma, keep it
                result.append(token)
                # Need a space after comma if not last element
                if next(token, None) != ',' and next(token, None) != '...':
                    result.append(' ')
            elif token == '...':
                # If last was a number or comma, need a space before three dots
                result.append(' ')
                result.append(token)

        last_type = token

    return ''.join(result)

s = input().strip()
output = solve(s)
