        answers = []

        # Count numbers satisfying condition 1: a > b and x mod a > b
        def count_condition1(l, r):
            count = 0
            if a > b:
                # x mod a > b means b < x < 2b
                low = max(b + 1, l)
                high = min(2 * b, r)
                if low <= high:
                    count += high - low + 1
            return count

        # Count numbers satisfying condition 2: b > a and x mod b > a
        def count_condition2(l, r):
            count = 0
            if b > a:
                # x mod b > a means a < x < 2a
                low = max(a + 1, l)
                high = min(2 * a, r)
                if low <= high:
                    count += high - low + 1
            return count

        # Count numbers satisfying both conditions
        def count_both(l, r):
            count = 0
            # If both conditions are true, then:
            # a > b and b < x < 2b
            # b > a and a < x < 2a
            # So x must be in the intersection of [b+1, 2b) and [a+1, 2a)
            if a > b and b > a:
                # This can't happen if a > b and b > a
                pass
            elif a > b:
                # b < x < 2b and x is also in [a+1, 2a)
                # So x must be in [max(b+1, a+1), min(2b, 2a))
                low = max(b + 1, a + 1, l)
                high = min(2 * b, 2 * a, r)
                if low <= high:
                    count += high - low + 1
            elif b > a:
                # a < x < 2a and x is also in [b+1, 2b)
                # So x must be in [max(a+1, b+1), min(2a, 2b))
                low = max(a + 1, b + 1, l)
                high = min(2 * a, 2 * b, r)
                if low <= high:
                    count += high - low + 1
            return count

        # Total valid numbers = condition1 + condition2 - both
        def count_valid(l, r):
