import sys

def solve(p, y):
    if p >= y:
        return -1

    # Find the maximum integer in [2, y] not divisible by any integer in [2, p]
    # equivalent to: no prime factor <= p

    def is_valid(k):
        # Check if k has any prime factor <= p
        # factor k and check
        if k == 1:
            return True  # 1 is not considered
        if k % 2 == 0:
            if 2 <= p:
                return False
        k1 = k
        i = 3
        while i * i <= k1:
            if k1 % i == 0:
                if i <= p:
                    return False
                # get the full factor
                while k1 % i == 0:
                    k1 //= i
            i += 2
        if k1 > 1:
            if k1 <= p:
                return False
        return True

    for k in range(y, 1, -1):
        if is_valid(k):
            return k
    return -1

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    p, y = map(int, data)
    res = solve(p, y)
    print(res)

if __name__ == '__main__':
    main()
"}

