import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    vols = [int(next(it)) for _ in range(n)]

    total = sum(vols)
    if total % n != 0:
        print("Unrecoverable configuration.")
    else:
        base = total // n
        diffs = [v - base for v in vols]
        non_zero = [d for d in diffs if d != 0]
        if not non_zero:
            print("Exemplary pages.")
        elif len(non_zero) == 2:
            d1, d2 = non_zero
            if abs(d1) == abs(d2):
                if d1 > 0 and d2 < 0:
                    a = vols.index(base + d1) + 1
                    b = vols.index(base + d2) + 1
                    v = abs(d1)
                    print(f"{v} ml. from cup #{a} to cup #{b}.")
                else:
                    print("Unrecoverable configuration.")
            else:
                print("Unrecoverable configuration.")
        else:
            print("Unrecoverable configuration.")

if __name__ == "__main__":
