import math
from collections import defaultdict

n, m, x = map(int, input().split())
keyboard = []
for _ in range(n):
    keyboard.append(input().strip())

letter_positions = defaultdict(list)
for i in range(n):
    for j in range(m):
        c = keyboard[i][j]
        if c == 'S':
            letter_positions['S'].append((i, j))
        else:
            letter_positions[c.lower()].append((i, j))

q = int(input())
text = input().strip()

# Precompute for each lowercase letter: can type with one hand (distance <= x) or not
# Also check if letter exists and 'S' exists
letter_can_one_hand = {}
for ch in 'abcdefghijklmnopqrstuvwxyz':
    positions = letter_positions.get(ch, [])
    s_positions = letter_positions.get('S', [])
    if not positions or not s_positions:
        letter_can_one_hand[ch] = False
    else:
        min_dist_sq = float('inf')
        for (i1, j1) in positions:
            for (i2, j2) in s_positions:
                dx = i1 - i2
                dy = j1 - j2
                dist_sq = dx * dx + dy * dy
                if dist_sq < min_dist_sq:
                    min_dist_sq = dist_sq
        letter_can_one_hand[ch] = min_dist_sq <= x * x

result = 0
for c in text:
    if c.islower():
        if not letter_positions[c]:
            print(-1)
            exit()
    else:
        c_lower = c.lower()
        if not letter_positions[c_lower] or not letter_positions['S']:
            print(-1)
            exit()
        if not letter_can_one_hand[c_lower]:
            result += 1

print(result)
