import sys

def solve():
    n = int(sys.stdin.readline())
    nums = list(map(int, sys.stdin.readline().split()))

    positive_sum = 0
    odd_numbers = []

    for num in nums:
        if num > 0:
            positive_sum += num
        if num % 2 == 1:
            odd_numbers.append(num)

    if positive_sum % 2 == 1:
        # Already odd
        print(positive_sum)
    else:
        # Need to include an odd number
        # Best option is: positive_sum + best_odd or positive_sum - worst_odd
        # Since we already have all positive numbers, best_odd would be the largest odd negative
        # worst_odd would be the smallest odd positive

        # If we include a negative odd, we add it (which is like subtracting from the sum)
        # If we include a positive odd, we subtract it

        max_odd_sum = -float('inf')

        # Try including each odd number
        for odd in odd_numbers:
            # If odd is positive, subtract it
            if odd > 0:
                candidate = positive_sum - odd
            # If odd is negative, add its absolute value (i.e., add it to sum)
            else:
                candidate = positive_sum + abs(odd)

            max_odd_sum = max(max_odd_sum, candidate)

        print(max_odd_sum)

if __name__ == "__main__":
