import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # compute parity of permutation (inversion count mod 2)
    # O(n log n) using Fenwick tree

    # to handle 1-index
    m = n
    class FenwickTree:
        def __init__(self, size):
            self.size = size
            self.tree = [0] * (self.size + 2)
        def add(self, idx, delta=1):
            while idx <= self.size:
                self.tree[idx] += delta
                idx += idx & -idx
        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

    ft = FenwickTree(m)
    inv = 0
    for i in range(n-1, -1, -1):
        inv += ft.query(m) - ft.query(arr[i])
        inv %= 2
        ft.add(arr[i])

    if inv == n % 2:
        print("Petr")
    else:
        print("Um_nik")

