def bisect_left(a, x):
    """Return the index where x should be inserted in a to maintain sorted order."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

