for _ in range(n):
    a, t, x = map(int, input().split())

    if a == 1:
        # Add x at time t
        if x not in add_times:
            add_times[x] = []
        # Insert t into add_times[x] maintaining sorted order
        i = bisect_left(add_times[x], t)
        add_times[x].insert(i, t)
    elif a == 2:
        # Remove x at time t
        if x not in remove_times:
            remove_times[x] = []
        # Insert t into remove_times[x] maintaining sorted order
        i = bisect_left(remove_times[x], t)
        remove_times[x].insert(i, t)
