        # Query: count x at time t
        if x not in add_times:
            add_count = 0
        else:
            add_count = bisect_left(add_times[x], t)  # number of adds <= t

        if x not in remove_times:
            remove_count = 0
        else:
            remove_count = bisect_left(remove_times[x], t)  # number of removes <= t

        print(add_count - remove_count)
