def format_string(s):
    # Split the string into tokens
    tokens = []
    i = 0
    n = len(s)

    while i < n:
        if s[i] == ',' or s[i] == ' ':
            # Handle spaces or commas
            if s[i] == ' ':
                # Count consecutive spaces
                j = i + 1
                while j < n and s[j] == '':
                    j += 1
                spaces = j - i
                tokens.append(('SPACE', spaces))
                i = j
            else:
                # Comma
                tokens.append(('COMMA', 1))
                i += 1
        elif s[i] == '.':
            # Check for three dots
            if i + 2 < n and s[i+1] == '.' and s[i+2] == '.':
                tokens.append(('DOTS', 3))
                i += 3
            else:
                # Not three dots, assume it's just a dot or part of something
                tokens.append(('OTHER', 1))
                i += 1
        else:
            # Number
            j = i + 1
            while j < n and s[j].isdigit() and not s[j].startswith('0') and len(s[j:]) > 1:
                j += 1
            tokens.append(('NUMBER', s[i:j]))
            i = j

    # Now process tokens
    result = []
    i = 0
    n = len(tokens)

    while i < n:
        token, data = tokens[i]

        if token == 'NUMBER':
            # Add the number
            result.append(data)
            # Look ahead to see what comes next
            if i + 1 < n:
                next_token, next_data = tokens[i + 1]
                if next_token == 'COMMA':
                    # Comma comes next
                    result.append(',')
                    result.append(' ')
                elif next_token == 'DOTS':
                    # Dots come next
                    result.append(' ')
                elif next_token == 'SPACE':
                    # Space between numbers
                    result.append(' ')
            i += 1
        elif token == 'COMMA':
            result.append(',')
            result.append(' ')
            i += 1
        elif token == 'DOTS':
            result.append(' ')
            result.append('...')
            i += 1
        elif token == 'SPACE':
            # Check if next is a number
            if i + 1 < n and tokens[i + 1][0] == 'NUMBER':
                result.append(' ')
                i += 1
            else:
                # Skip spaces
                i += 1

    return ''.join(result)

