            result.append(s[i:j])
            i = j

    return ''.join(result)

s = input().strip()
print(format_sequence(s))

def format_sequence(s):
    result = []
    i = 0
    n = len(s)

    while i < n:
        if s[i] == ',':
            # Add comma
            result.append(',')
            # Add space after comma (unless it's the last character)
            if i + 1 < n:
                result.append(' ')
            i += 1
        elif s[i] == '':
            # Collapse spaces to a single space
            if not result or result[-1] != '':
                result.append(' ')
            i += 1
        elif s[i:i+3] == '...':
            # Add three dots
            result.append('...')
            # Add space before three dots (unless at the beginning)
            if result and result[-1] not in ',':
                result.append(' ')
            i += 3
        else:
            # This is a number
            j = i
            while j < n and s[j] not in ',... ':
                j += 1
            result.append(s[i:j])
            i = j

    return ''.join(result)

s = input().strip()
print(format_sequence(s))

