n = int(input())
teams = {}
for _ in range(n):
    name = input().strip()
    teams[name] = {
        'points': 0,
        'diff': 0,
        'scored': 0
    }

for _ in range(n * (n - 1) // 2):
    match = input().strip()
    # Split match info
    parts = match.split()
    teams1, teams2 = parts[0].split('-')
    score1, score2 = map(int, parts[1].split(':'))

    # Update team stats
    for team, score in [(teams1, score1), (teams2, score2)]:
        teams[team]['scored'] += score
        teams[team]['diff'] += score

    # Award points
    if score1 > score2:
        teams[teams1]['points'] += 3
    elif score1 == score2:
        teams[teams1]['points'] += 1
        teams[teams2]['points'] += 1
    else:
        teams[teams2]['points'] += 3

# Sort teams by criteria: points (desc), diff (desc), scored (desc)
sorted_teams = sorted(teams.keys(), key=lambda name: (
    -teams[name]['points'],
    -teams[name]['diff'],
    -teams[name]['scored']
))

# Output top n/2 teams sorted lexicographically
for i in range(n // 2):
    print(sorted_teams[i])
