import sys

def solve():
    input = sys.stdin.read().split()
    data = list(map(int, input))
    idx = 0
    t = data[idx]
    idx += 1

    # For each test case
    for _ in range(t):
        n = data[idx]
        m = data[idx+1]
        a = data[idx+2]
        b = data[idx+3]
        idx += 4

        # Build adjacency list
        adj = [[] for _ in range(n+1)]
        for _ in range(m):
            u = data[idx]
            v = data[idx+1]
            idx += 2
            adj[u].append(v)
            adj[v].append(u)

        # Use Union-Find (Disjoint Set Union) to find components
        # We need to find components after removing a and b

        # First, find component of a
        parent = {}

        # Function to find root
        def find(x):
            if x not in parent:
                parent[x] = x
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        # Function to union
        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        # Union all nodes except a and b
        for node in range(1, n+1):
            if node != a and node != b:
                for neighbor in adj[node]:
                    if neighbor != a and neighbor != b:
                        union(node, neighbor)

        # Now find component of a and component of b
        # Actually, we need to find the component that contains a (excluding a itself)
        # And the component that contains b (excluding b itself)

        # Find component that contains a
        component_a = set()
        for node in range(1, n+1):
            if node != a and node != b:
                if find(node) == find(a):
                    component_a.add(node)
        count_a = len(component_a)

        # Find component that contains b
        component_b = set()
        for node in range(1, n+1):
            if node != a and node != b:
                if find(node) == find(b):
                    component_b.add(node)
        count_b = len(component_b)

        # If components are different, answer is count_a * count_b
        print(count_a * count_b)

if __name__ == '__main__':
    solve()
"}

