        for i in range(n):
            # Who is attacking player i?
            attack_from_left = s[i-1] == 'R' if i > 0 else s[n-1] == 'R'
            attack_from_right = s[i+1] == 'L' if i < n-1 else s[0] == 'L'

            attackers = []
            if attack_from_left:
                attackers.append((i-1) % n)
            if attack_from_right:
                attackers.append((i+1) % n)

            if len(attackers) == 1:
                # They must attack that attacker
                if attackers[0] != (i - 1) % n:
                    # Player i is attacking the wrong player, we need to change something
                    changes += 1
