                # They are attacked by 2 players, they can attack either
                # We need to check if they are attacking the right player
                if s[i] == 'L':
                    # They're attacking left, they should attack the left attacker if that's one of the attackers
                    if (i-1) % n == attackers[0] or (i-1) % n == attackers[1]:
