import sys

n, m, k = map(int, sys.stdin.readline().split())

# Dictionary to hold flights: key = (from_city, to_city), value = list of (day, cost)
flights = {}

for _ in range(m):
    d, f, t, c = map(int, sys.stdin.readline().split())

    # Store flights in both directions if they are bidirectional
    if f == 0 and t != 0:
        flights[(0, t)] = flights.get((0, t), []) + [(d, c)]
    elif t == 0 and f != 0:
        flights[(f, 0)] = flights.get((f, 0), []) + [(d, c)]

# Find minimum cost to reach Metropolis from each city on each day
reach = {i: {0: float('inf')} for i in range(n + 1)}
leave = {i: {0: float('inf')} for i in range(n + 1)}

# Initialize reach costs from each city to Metropolis
for city in range(1, n + 1):
    reach[city][0] = float('inf')
    leave[city][0] = float('inf')

# Update reach costs from each city to Metropolis
for i in range(1, n + 1):
    for day, cost in flights.get((i, 0), []):
        reach[i][day] = cost

    # Propagate to later days
    for day in sorted(reach[i].keys()):
        if day != 0:
            for later_day, _ in flights.get((i, 0), []):
                if later_day >= day and later_day not in reach[i]:
                    reach[i][later_day] = reach[i][day]

# Update leave costs from Metropolis to each city
for i in range(1, n + 1):
    for day, cost in flights.get((0, i), []):
        leave[i][day] = cost

    # Propagate to later days
    for day in sorted(leave[i].keys()):
        if day != 0:
            for later_day, _ in flights.get((0, i), []):
                if later_day >= day and later_day not in leave[i]:
                    leave[i][later_day] = leave[i][day]

# Find minimum cost to gather everyone for k days
min_total_cost = float('inf')

# Try all possible arrival/departure day windows
for arrival_day in range(1, n + 1):
    for departure_day in range(arrival_day + k, n + 1):
        total_cost = 0

        # Calculate total cost for all jury members
        valid = True
        for city in range(1, n + 1):
            # Find minimum cost to arrive by arrival_day
            min_reach = min(reach[city].get(d, float('inf')) for d in range(arrival_day + 1))
            if min_reach == float('inf'):
                valid = False
                break

            # Find minimum cost to depart on or after departure_day
            min_leave = min(leave[city].get(d, float('inf')) for d in range(departure_day, n + 1))
            if min_leave == float('inf'):
                valid = False
                break

            total_cost += min_reach + min_leave

        if valid:
            min_total_cost = min(min_total_cost, total_cost)

if min_total_cost != float('inf'):
    print(min_total_cost)
else:
    print(-1)
