{"code": "
n, m, k = map(int, input().split())
grid = [list(input().strip()) for _ in range(n)]

# Track the positions of each spider at each time
# We'll use a dictionary to count spiders at each (time, row, col)
spiders = {}

# Record the initial positions
for i in range(n):
    for j in range(m):
        cell = grid[i][j]
        if cell in 'RLUD':
            spiders[(0, i, j)] = cell

# Trace each spider's path
for time, row, col in list(spiders.keys()):
    cell = spiders[(time, row, col)]
    if cell == 'L':
        # Move left
        for t in range(time + 1, n + 1):
            new_row = row
            new_col = col - (t - time)
            if new_col >= 0:
                spiders[(t, new_row, new_col)] = cell
            else:
                break
    elif cell == 'R':
        # Move right
        for t in range(time + 1, n + 1):
            new_row = row
            new_col = col + (t - time)
            if new_col < m:
                spiders[(t, new_row, new_col)] = cell
            else:
                break
    elif cell == 'U':
        # Move up
        for t in range(time + 1, n + 1):
            new_row = row - (t - time)
            new_col = col
            if new_row >= 0:
                spiders[(t, new_row, new_col)] = cell
            else:
                break
    elif cell == 'D':
        # Move down
        for t in range(time + 1, n + 1):
            new_row = row + (t - time)
            new_col = col
            if new_row < n:
                spiders[(t, new_row, new_col)] = cell
            else:
                break

# Now trace Om Nom's path from each starting position
result = []
for start_col in range(m):
    seen = 0
    for time in range(n):
        row = time
        col = start_col
        # If Om Nom is still in bounds, check if there are spiders at this position
        if row < n and col < m:
            seen += spiders.get((time, row, col), 0)
    result.append(str(seen))

print(' '.join(result)
