        visited = [False] * (n + 1)
        comp_id = 0

        def dfs_remove_city(u, excluded_city):
            if u == excluded_city:
                return

            visited[u] = True
            for v in adj[u]:
                if v != excluded_city and not visited[v]:
                    dfs_remove_city(v, excluded_city)

        # Count components when removing a
        comp_count_a = 0
        for u in range(1, n + 1):
            if u != a and not visited[u]:
                comp_count_a += 1
                dfs_remove_city(u, a)

