        visited = [False] * (n + 1)
        comp_count_b = 0
        for u in range(1, n + 1):
            if u != b and not visited[u]:
                comp_count_b += 1
                dfs_remove_city(u, b)

        # Actually, we need more than just the number of components
        # We need to know which cities are in which component
        visited = [False] * (n + 1)
        component_a = [0] * (n + 1)
        comp_id = 0

        def dfs_remove_city_with_id(u, excluded_city, comp_id):
            if u == excluded_city:
                return

            visited[u] = True
            component_a[u] = comp_id
            for v in adj[u]:
                if v != excluded_city and not visited[v]:
                    dfs_remove_city_with_id(v, excluded_city, comp_id)

        for u in range(1, n + 1):
            if u != a and not visited[u]:
                comp_id += 1
                dfs_remove_city_with_id(u, a, comp_id)

        # Count cities in each component when removing a
        comp_count_a = [0] * (comp_id + 1)
        for u in range(1, n + 1):
            if u != a:
                comp_count_a[component_a[u]] += 1

        visited = [False] * (n + 1)
        component_b = [0] * (n + 1)
        comp_id = 0

        for u in range(1, n + 1):
            if u != b and not visited[u]:
                comp_id += 1
                dfs_remove_city_with_id(u, b, comp_id)

        comp_count_b = [0] * (comp_id + 1)
        for u in range(1, n + 1):
            if u != b:
                comp_count_b[component_b[u]] += 1

        # Now we have comp_count_a and comp_count_b
        # But we need to relate the components from both removals
        # We need to know which component in a's graph corresponds to which component in b's graph

        # Create a mapping from a's component to b's component
        a_to_b = {}  # maps component id in a's graph to component id in b's graph

        for u in range(1, n + 1):
            if u != a and u != b:
