n, times = map(int, open(0).read().split())

people = []
for i in range(n):
    people.append((times[i], i + 1))  # (time, index)

queue = people.copy()
result_pairs = []

while len(queue) > 1:
    # Take first 3 people
    first_three = queue[:3]

    # Find the person with the smallest time
    min_time = float('inf')
    min_index = -1

    for person in first_three:
        if person[0] < min_time:
            min_time = person[0]
            min_index = first_three.index(person)

    # Remove the person with the smallest time from consideration
    if min_index == 0:
        first_three.pop(0)
    elif min_index == 1:
        first_three.pop(1)
    else:
        first_three.pop(2)

    # The remaining 2 people are the ones with the largest times
    result_pairs.append([first_three[0][1], first_three[1][1]])

    # Remove both served people from the queue
    if min_index == 0:
        queue.pop(0)
        queue.pop(0)
    elif min_index == 1:
        queue.pop(1)
        queue.pop(0)
    else:
        queue.pop(2)
        queue.pop(1)

# If one person remains, add them
if len(queue) == 1:
    result_pairs.append([queue[0][1]])

# Calculate total time
total_time = 0
for pair in result_pairs:
    if len(pair) == 2:
        a_idx, b_idx = pair
        a_time, b_time = times[a_idx - 1], times[b_idx - 1]
        total_time += max(a_time, b_time)
    else:
        c_idx = pair[0]
        total_time += times[c_idx - 1]

# Output
print(total_time)
for pair in result_pairs:
    if len(pair) == 2:
        print(f"{pair[0]} {pair[1]}")
    else:
        print(pair[0])
