import sys
import math

def generate_primes(n):
    if n == 0:
        return []
    primes = []
    candidate = 2
    while len(primes) < n:
        is_prime = True
        sqrt_c = int(math.isqrt(candidate)) + 1
        for p in primes:
            if p > sqrt_c:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1
    return primes

n = int(sys.stdin.readline())
if n == 1:
    print(2)
else:
    primes = generate_primes(n)
    print(' '.join(map(str, primes)))
"}

