import math

def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        if k >= n:
            print(1)
            continue
        best = 0
        # Find largest divisor of n <= k
        # Check all divisors up to sqrt(n)
        sqrt_n = math.isqrt(n)
        for i in range(1, sqrt_n + 1):
            if n % i == 0:
                if i <= k:
                    best = max(best, i)
                j = n // i
                if j <= k:
                    best = max(best, j)
        if best == 0:
            # Only divisor <=k is 1 (since 1 <=k always)
            best = 1
        print(n // best)

if __name__ == "__main__":
    solve()
"}

