import sys

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    # a is 0-indexed, floors 1..n
    min_total = float('inf')
    for x in range(1, n + 2):  # try x from 1 to n+1 (just n is fine, but n+1 may also be better)
        total = 0
        for i in range(1, n + 1):
            people = a[i - 1]
            if people > 0:
                dist = abs(x - i) + abs(i - 1) + abs(x - 1)
                total += people * 2 * dist
        if total < min_total:
            min_total = total
    print(min_total)

if __name__ == "__main__":
    solve()
"}

