def find_max_odd_subsequence_sum(n, a):
    positives = [x for x in a if x > 0]
    negatives = [x for x in a if x < 0]

    sum_pos = sum(positives)

    # If sum of positives is odd, that's our answer
    if sum_pos % 2 == 1:
        return sum_pos

    # If sum of positives is even, we need to adjust
    # Find the smallest odd positive number (to remove)
    smallest_odd_positive = None
    for num in positives:
        if num % 2 == 1:
            if smallest_odd_positive is None or num < smallest_odd_positive:
                smallest_odd_positive = num

    # Find the largest odd negative number (to add)
    largest_odd_negative = None
    for num in negatives:
        if num % 2 == 1:
            if largest_odd_negative is None or num > largest_odd_negative:
                largest_odd_negative = num

    # If we can't adjust, the problem guarantees we can
    if smallest_odd_positive is None and largest_odd_negative is None:
        return sum_pos

    # Choose the better option
    if smallest_odd_positive is None:
        return sum_pos + largest_odd_negative
    elif largest_odd_negative is None:
        return sum_pos - smallest_odd_positive
    else:
        return max(sum_pos - smallest_odd_positive, sum_pos + largest_odd_negative)

