def parity_check(perm):
    """Calculate the parity of a permutation (even: 0, odd: 1)"""
    inversions = 0
    n = len(perm)

    for i in range(n):
        for j in range(i + 1, n):
            if perm[i] > perm[j]:
                inversions += 1

    return inversions % 2

def solve():
    n = int(input())
    perm = list(map(int, input().split()))

    # Calculate parity
    parity = parity_check(perm)

    # Determine method based on parity and n
    # For even n:
    # - Petr: 3n swaps (even) → even parity
    # - Alex: 7n+1 swaps (odd) → odd parity
    #
    # For odd n:
    # - Petr: 3n swaps (odd) → odd parity
    # - Alex: 7n+1 swaps (even) → even parity

    if n % 2 == 0:
        # Even n
        if parity == 0:
            print("Petr")
        else:
            print("Um_nik")
    else:
        # Odd n
        if parity == 1:
            print("Petr")
        else:
            print("Um_nik")

solve()
